#include <cstdint>
#include <optional>
#include <vector>

struct InlineHook
{
    std::vector<std::uint8_t> patch;
    std::vector<std::uint8_t> trampoline;
};

static bool relativeAt(const std::vector<std::uint8_t>& b, std::size_t at)
{
    const std::uint8_t op{ b[at] };
    if (op == 0xE8 || op == 0xE9 || op == 0xEB || (op >= 0x70 && op <= 0x7F)) return true;
    return op == 0x0F && at + 1 < b.size() && b[at + 1] >= 0x80 && b[at + 1] <= 0x8F;
}

static bool jump(std::vector<std::uint8_t>& out, std::uint64_t from, std::uint64_t to)
{
    const auto disp{ static_cast<std::int64_t>(to - (from + 5)) };
    if (disp < INT32_MIN || disp > INT32_MAX) return false;
    out.push_back(0xE9);
    const auto u{ static_cast<std::uint32_t>(static_cast<std::int32_t>(disp)) };
    for (int i{ 0 }; i < 4; ++i) out.push_back(static_cast<std::uint8_t>(u >> (8 * i)));
    return true;
}

std::optional<InlineHook> planHook(const std::vector<std::uint8_t>& functionStart, const std::vector<std::size_t>& lengths,
                                   std::uint64_t target, std::uint64_t hook, std::uint64_t trampolineAt)
{
    std::size_t stolen{ 0 };
    for (std::size_t length : lengths)
    {
        if (stolen >= 5) break;
        if (stolen >= functionStart.size() || relativeAt(functionStart, stolen)) return std::nullopt;
        stolen += length;
    }
    if (stolen < 5 || stolen > functionStart.size()) return std::nullopt;

    InlineHook h;
    if (!jump(h.patch, target, hook)) return std::nullopt;
    h.patch.resize(stolen, 0x90);
    h.trampoline.assign(functionStart.begin(), functionStart.begin() + static_cast<std::ptrdiff_t>(stolen));
    if (!jump(h.trampoline, trampolineAt + stolen, target + stolen)) return std::nullopt;
    return h;
}

std::uint64_t hookIat(std::vector<std::uint64_t>& iat, std::size_t slot, std::uint64_t replacement)
{
    const std::uint64_t original{ iat[slot] };
    iat[slot] = replacement;
    return original;
}

