using Bytes = std::vector<std::uint8_t>;
static Bytes start() { return { 0x48, 0x89, 0x5C, 0x24, 0x08, 0x57, 0x48, 0x83, 0xEC, 0x20 }; }

TEST("a hook over one 5-byte instruction") {
    const auto h{ planHook(start(), { 5, 1, 4 }, 0x140001000, 0x140008000, 0x140009000) };
    CHECK(h.has_value());
    if (!h) return;
    CHECK(h->patch == (Bytes{ 0xE9, 0xFB, 0x6F, 0x00, 0x00 }));
    CHECK(h->trampoline == (Bytes{ 0x48, 0x89, 0x5C, 0x24, 0x08, 0xE9, 0xFB, 0x7F, 0xFF, 0xFF }));
}
TEST("stealing several instructions pads with nops") {
    const Bytes code{ 0x40, 0x53, 0x56, 0x48, 0x83, 0xEC, 0x20, 0x8B, 0xD9 };
    const auto h{ planHook(code, { 2, 1, 4, 2 }, 0x140002000, 0x140002100, 0x140003000) };
    CHECK(h.has_value());
    if (!h) return;
    CHECK_EQ(h->patch.size(), 7u);
    CHECK(h->patch[5] == 0x90 && h->patch[6] == 0x90);
    CHECK_EQ(h->trampoline.size(), 12u);
    CHECK(Bytes(h->trampoline.begin(), h->trampoline.begin() + 7) == Bytes(code.begin(), code.begin() + 7));
    CHECK(Bytes(h->trampoline.begin() + 7, h->trampoline.end()) == (Bytes{ 0xE9, 0xFB, 0xEF, 0xFF, 0xFF }));
}
TEST("cases a hook cannot handle") {
    CHECK(!planHook({ 0xE9, 0, 0, 0, 0, 0x90 }, { 5, 1 }, 0x1000, 0x2000, 0x3000).has_value());
    CHECK(!planHook({ 0x90, 0x74, 0x02, 0x90, 0x90 }, { 1, 2, 1, 1 }, 0x1000, 0x2000, 0x3000).has_value());
    CHECK(!planHook({ 0x90, 0x90 }, { 1, 1 }, 0x1000, 0x2000, 0x3000).has_value());
    CHECK(!planHook(start(), { 5 }, 0x140001000, 0x7FF600000000, 0x140009000).has_value());
}
TEST("IAT hooks") {
    std::vector<std::uint64_t> iat{ 0x7FFA10001000, 0x7FFA10002000, 0 };
    const std::uint64_t original{ hookIat(iat, 1, 0x140005000) };
    CHECK_EQ(original, 0x7FFA10002000ull);
    CHECK_EQ(iat[1], 0x140005000ull);
    CHECK_EQ(hookIat(iat, 1, original), 0x140005000ull);
    CHECK_EQ(iat[1], 0x7FFA10002000ull);
}

